/* Savage test   floating point speed and accuracy test   Byte Jul.87 p. 106   typed by O.E.Tutzauer					*/   #define NLOOPS	1000extern double tan(), atan(), exp(), log(), sqrt();main(){int i;double a;	printf("start \n");	a = 1.0;	for (i=1; i<=(NLOOPS - 1); i++)			a = tan(atan(exp(log(sqrt(a*a))))) + 1.0;		printf("a = %20.14e\n",a);	printf("%d loops done \n",NLOOPS );}